from numba import njit

@njit
def old_style(dt, bins, bin_size, autocorr):
    radial_sum = np.zeros_like(bins[:-1], dtype=np.float64)
    for i, r in enumerate(bins[:-1]):
        mask = (dt <= r) * (dt > (r - bin_size[i]))
        radial_sum[i] = np.sum(np.ravel(autocorr)[np.ravel(mask)], dtype=np.int64) / np.sum(mask, dtype=np.int64)
    return radial_sum

rng=np.random.default_rng(0)
dt=rng.random((4,5,6)); bins=np.array([0.,0.1,0.2,0.3]); bs=np.diff(bins); ac=rng.random((4,5,6))
try:
    out=old_style(dt,bins,bs,ac)
    print('old out', out)
except Exception as e:
    print('old raised', type(e).__name__, e)

@njit
def new_style(dt,bins,autocorr):
    out=np.zeros(len(bins)-1,dtype=np.float64)
    flat=np.ravel(autocorr)
    for i in range(len(bins)-1):
        if i<len(bins)-2:
            mask=(dt>=bins[i])&(dt<bins[i+1])
        else:
            mask=(dt>=bins[i])&(dt<=bins[i+1])
        mask=np.ravel(mask)
        count=np.sum(mask)
        if count>0:
            out[i]=np.sum(flat[mask])/count
    return out
